}

/// Base label for a marketplace tab: the official curated marketplace is always
/// labeled `OpenAI Curated`; other marketplaces use their display name.
fn marketplace_tab_base_label(marketplace: &PluginMarketplaceEntry) -> String {
    if is_curated_marketplace(marketplace) {
        "OpenAI Curated".to_string()
    } else {
        marketplace_display_name(marketplace)
    }
}

