/// slice). When multiple marketplaces resolve to the same base label, each is
/// disambiguated with a `Name (K/N)` suffix, where `K` is the 1-based
/// occurrence and `N` the total number sharing that label.
fn marketplace_tab_labels(marketplaces: &[&PluginMarketplaceEntry]) -> Vec<String> {
    let base_labels: Vec<String> = marketplaces
        .iter()
        .map(|marketplace| marketplace_tab_base_label(marketplace))
        .collect();

    let mut totals: std::collections::HashMap<&str, usize> = std::collections::HashMap::new();
    for label in &base_labels {
        *totals.entry(label.as_str()).or_insert(0) += 1;
    }

    let mut seen: std::collections::HashMap<&str, usize> = std::collections::HashMap::new();
    base_labels
        .iter()
        .map(|label| {
            let total = totals.get(label.as_str()).copied().unwrap_or(1);
            if total <= 1 {
                label.clone()
            } else {
                let occurrence = seen.entry(label.as_str()).or_insert(0);
                *occurrence += 1;
                format!("{label} ({occurrence}/{total})")
            }
        })
        .collect()
